cd /workspace && node -e "
const fs = require('fs');
const pdfjsLib = require('pdfjs-dist');

async function extractText() {
  const data = new Uint8Array(fs.readFileSync('/workspace/testbed/docs/handbook.pdf'));
  const doc = await pdfjsLib.getDocument({ data }).promise;
  let fullText = '';

  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i);
    const content = await page.getTextContent();
    const strings = content.items.map(item => item.str);
    fullText += strings.join(' ') + '\n\n';
  }

  const outputPath = '/workspace/testbed/docs/handbook.txt';
  fs.writeFileSync(outputPath, fullText);
  console.log('Pages:', doc.numPages);
  console.log('Characters:', fullText.length);
  console.log('Saved to:', outputPath);
}

extractText().catch(err => console.error('Error:', err.message));
"
